body:
digraph G {
  rankdir=LR;
  node [shape=box, style="rounded,filled", fillcolor="#eef4ff", color="#4f7ccf"];
  Source [label="Markdown"];
  Parse [label="解析"];
  Render [label="渲染"];
  Export [label="导出", shape=folder, fillcolor="#eef8ef"];
  Source -> Parse -> Render -> Export;
  Parse -> Source [label="修正", style=dashed];
}

\begin{aligned}
A &= \pi r^2 \\
V &= \frac{4}{3}\pi r^3
\end{aligned}

{
  "data": { "values": [
    { "stage": "发现", "count": 20 },
    { "stage": "预览", "count": 17 },
    { "stage": "导出", "count": 15 },
    { "stage": "交付", "count": 12 }
  ] },
  "mark": { "type": "bar", "cornerRadiusEnd": 4 },
  "encoding": {
    "x": { "field": "stage", "type": "nominal", "axis": { "title": "工作阶段" } },
    "y": { "field": "count", "type": "quantitative", "axis": { "title": "能力数" } },
    "color": { "field": "stage", "type": "nominal", "legend": null }
  }
}

{ signal: [
  { name: 'clk',  wave: 'p..P..p.' },
  { name: 'req',  wave: '0.1..0..', data: ['请求'] },
  { name: 'data', wave: 'x.3..x..', data: ['payload'] },
  { name: 'ack',  wave: '0...1.0.' }
], head: { text: '请求 / 应答时序' } }

workspace "All Charts Structurizr" {
  model {
    user = person "用户"
    app = softwareSystem "MD Viewer" {
      renderer = container "RendererPlugin"
      exporter = container "Export Pipeline"
    }
    service = softwareSystem "DOCX Service"
    user -> app "预览 Markdown"
    renderer -> exporter "输出 SVG"
    exporter -> service "生成 DOCX"
  }
}

{
  "data": [
    { "type": "bar", "name": "预览", "x": ["架构", "流程", "数据"], "y": [18, 14, 11] },
    { "type": "bar", "name": "导出", "x": ["架构", "流程", "数据"], "y": [16, 13, 10] }
  ],
  "layout": { "title": "图表能力覆盖", "barmode": "group", "height": 420 }
}

Table users {
  id int [pk, increment]
  name varchar
  email varchar [unique]
}
Table documents {
  id int [pk, increment]
  owner_id int [not null]
  path varchar
  updated_at datetime
}
Table export_tasks {
  id int [pk, increment]
  document_id int [not null]
  format varchar
}
Ref: documents.owner_id > users.id
Ref: export_tasks.document_id > documents.id

{
  "title": "Markdown 处理拓扑",
  "nodes": [
    { "id": "source", "label": "Markdown" },
    { "id": "parser", "label": "解析器" },
    { "id": "renderer", "label": "RendererPlugin" },
    { "id": "preview", "label": "预览" },
    { "id": "export", "label": "导出" }
  ],
  "edges": [
    { "source": "source", "target": "parser" },
    { "source": "parser", "target": "renderer" },
    { "source": "renderer", "target": "preview" },
    { "source": "renderer", "target": "export" }
  ]
}
